def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 = x^2*y^2*z^2"""
    lhs = x**3 + y**3 + z**3
    rhs = x**2 * y**2 * z**2
    return lhs == rhs

solutions = []
X_max = 1
Y_max = 3
Z_max = 3

for x in range(1, X_max + 1):
    for y in range(x, Y_max + 1):
        for z in range(y, Z_max + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))
            # print(f"Checking ({x}, {y}, {z}): LHS={x**3 + y**3 + z**3}, RHS={x**2 * y**2 * z**2}")

print("Solutions found:", solutions)

